@Controller
public class UserController {
    @GetMapping("/users")
    public String showUsers(Model model) {
        List<User> users = userService.findAll();
        model.addAttribute("users", users);  // put data into model
        model.addAttribute("count", users.size());
        return "users"; // template name
    }
}

// In Thymeleaf template (users.html):
// <tr th:each="user : ${users}"> ... </tr>
// Total: <span th:text="${count}"></span>
